import type { PrismaClient, Prisma } from "@prisma/client";

type ProductStructureCommandRecord = Prisma.ProductStructureCommandGetPayload<{}>;

export type CreateAcceptedCommandInput = {
  externalRequestId: string;
  productCode: string;
  commandType: "SYNC" | "APPLY" | "DELETE";
  source?: "API2" | "JOB" | "ADMIN";
};

export class ProductStructureCommandStore {
  constructor(private readonly prisma: PrismaClient) {}

  async findByExternalRequestId(
    externalRequestId: string
  ): Promise<ProductStructureCommandRecord | null> {
    return this.prisma.productStructureCommand.findUnique({
      where: { externalRequestId },
    });
  }

  /**
   * Idempotência: cria ACCEPTED se não existir, senão retorna o existente.
   * Regra: o mesmo externalRequestId nunca deve reexecutar o comando.
   */
  async getOrCreateAccepted(
    input: CreateAcceptedCommandInput
  ): Promise<{ record: ProductStructureCommandRecord; created: boolean }> {
    const existing = await this.findByExternalRequestId(input.externalRequestId);
    if (existing) return { record: existing, created: false };

    const record = await this.prisma.productStructureCommand.create({
      data: {
        externalRequestId: input.externalRequestId,
        productCode: input.productCode,
        commandType: input.commandType,
        status: "ACCEPTED",
        source: input.source ?? "API2",
        executedAt: new Date(),
      },
    });

    return { record, created: true };
  }

  async markConfirmed(externalRequestId: string): Promise<ProductStructureCommandRecord> {
    return this.prisma.productStructureCommand.update({
      where: { externalRequestId },
      data: {
        status: "CONFIRMED",
        completedAt: new Date(),
        lastError: null,
      },
    });
  }

  async markFailed(externalRequestId: string, error: unknown): Promise<ProductStructureCommandRecord> {
    const normalized =
      error instanceof Error
        ? { message: error.message, name: error.name, stack: error.stack }
        : { message: String(error) };

    return this.prisma.productStructureCommand.update({
      where: { externalRequestId },
      data: {
        status: "FAILED",
        completedAt: new Date(),
        lastError: normalized as any,
      },
    });
  }

  async countByStatus(status: "ACCEPTED" | "CONFIRMED" | "FAILED"): Promise<number> {
    return this.prisma.productStructureCommand.count({ where: { status } });
  }

  async lastForProduct(productCode: string): Promise<ProductStructureCommandRecord | null> {
    return this.prisma.productStructureCommand.findFirst({
      where: { productCode },
      orderBy: { createdAt: "desc" },
    });
  }
}