import {
  OmieClientGateway,
  OmieClientRaw,
} from "../../../application/ports/omie-client-gateway.port";

import type { OmieHttpClientPort } from "@/shared/integrations/omie/omie-http-client.port";

// Omie costuma retornar "clientes_cadastro" em listagens (e não "clientes").
// Vamos suportar ambos para não ficar frágil.
interface OmieListClientsResponse {
  clientes?: OmieClientRaw[];
  clientes_cadastro?: OmieClientRaw[];
  total_de_registros?: number;
  total_de_paginas?: number;
}

type OmieConsultarClienteResponse = OmieClientRaw & {
  faultstring?: string;
  faultcode?: string;
  error?: string;
};

export class OmieClientGatewayImpl implements OmieClientGateway {
  constructor(private readonly omieClient: OmieHttpClientPort) {}

  async listClients(page: number): Promise<OmieClientRaw[]> {
    const response = await this.omieClient.post<OmieListClientsResponse>(
      "/api/v1/geral/clientes/",
      {
        call: "ListarClientes",
        param: [
          {
            pagina: page,
            registros_por_pagina: 50,
          },
        ],
      }
    );

    return response.clientes ?? response.clientes_cadastro ?? [];
  }

  async getClientByCode(omieClientCode: bigint): Promise<OmieClientRaw | null> {
    const codeAsNumber = Number(omieClientCode);

    // tentativa 1: codigo_cliente_omie
    try {
      const resp1 = await this.omieClient.post<OmieConsultarClienteResponse>(
        "/api/v1/geral/clientes/",
        {
          call: "ConsultarCliente",
          param: [{ codigo_cliente_omie: codeAsNumber }],
        }
      );

      if (resp1?.faultstring || resp1?.error) return null;
      if (resp1?.razao_social || resp1?.cnpj_cpf || resp1?.codigo_cliente_omie) return resp1;
    } catch {
      // segue
    }

    // tentativa 2: codigo_cliente
    try {
      const resp2 = await this.omieClient.post<OmieConsultarClienteResponse>(
        "/api/v1/geral/clientes/",
        {
          call: "ConsultarCliente",
          param: [{ codigo_cliente: codeAsNumber }],
        }
      );

      if (resp2?.faultstring || resp2?.error) return null;
      if (resp2?.razao_social || resp2?.cnpj_cpf || resp2?.codigo_cliente_omie) return resp2;

      return null;
    } catch {
      return null;
    }
  }
}